+// 데이터 타입 검증 및 변환 함수
+const validateAndConvertValue = (value: any, expectedType: string, columnName: string, rowIndex: number) => {
+  const errors: string[] = [];
+  
+  switch (expectedType) {
+    case 'string':
+      return { value: String(value || ''), errors };
+      
+    case 'number':
+      if (value === null || value === undefined || value === '') {
+        return { value: 0, errors: [`행 ${rowIndex + 1}, 컬럼 '${columnName}': 빈 값을 0으로 변환했습니다.`] };
+      }
+      const numValue = Number(value);
+      if (isNaN(numValue)) {
+        return { 
+          value: 0, 
+          errors: [`행 ${rowIndex + 1}, 컬럼 '${columnName}': '${value}'는 숫자가 아닙니다. 0으로 변환했습니다.`] 
+        };
+      }
+      return { value: numValue, errors };
+      
+    case 'boolean':
+      if (typeof value === 'boolean') {
+        return { value, errors };
+      }
+      if (typeof value === 'string') {
+        const lowerValue = value.toLowerCase();
+        if (['true', '1', 'y', 'yes', '참', 'o'].includes(lowerValue)) {
+          return { value: true, errors };
+        }
+        if (['false', '0', 'n', 'no', '거짓', 'x'].includes(lowerValue)) {
+          return { value: false, errors };
+        }
+      }
+      return { 
+        value: false, 
+        errors: [`행 ${rowIndex + 1}, 컬럼 '${columnName}': '${value}'를 boolean으로 변환할 수 없어 false로 설정했습니다.`] 
+      };
+      
+    default:
+      return { value: String(value || ''), errors };
+  }
+};
