+    }
+    
+    // 타입 검증
+    if (uploadCol.type !== originalCol.type) {
+      errors.push(`컬럼 '${uploadCol.name}'의 타입이 다릅니다. 원본: '${originalCol.type}', 업로드: '${uploadCol.type}'`);
+    }
+    
+    // 필수 여부 검증
+    if (uploadCol.required !== originalCol.required) {
+      errors.push(`컬럼 '${uploadCol.name}'의 필수 여부가 다릅니다. 원본: ${originalCol.required ? 'Y' : 'N'}, 업로드: ${uploadCol.required ? 'Y' : 'N'}`);
+    }
+  });
+  
+  return errors;
+};
