+// 데이터 검증 및 분류 함수
+const validateAndClassifyData = (data: any[], columns: any[]) => {
+  const successData: any[] = [];
+  const failedData: any[] = [];
+  const dataErrors: string[] = [];
+  
+  data.forEach((item, index) => {
+    const rowErrors: string[] = [];
+    let hasValidationErrors = false;
+    
+    // 각 필드 검증
+    columns.forEach(column => {
+      const value = item[column.name];
+      const fieldName = column.name;
+      const rowNum = index + 1;
+      
+      // 필수 필드 검증
+      if (column.required && (value === null || value === undefined || value === '')) {
+        rowErrors.push(`행 ${rowNum}: '${fieldName}' 필드는 필수입니다.`);
+        hasValidationErrors = true;
+        return;
+      }
+      
+      // 타입 검증
+      if (value !== null && value !== undefined && value !== '') {
+        switch (column.type) {
+          case 'number':
+            if (isNaN(Number(value))) {
+              rowErrors.push(`행 ${rowNum}: '${fieldName}' 필드는 숫자여야 합니다. (현재 값: ${value})`);
+              hasValidationErrors = true;
+            }
+            break;
+          case 'boolean':
+            if (typeof value === 'string') {
+              const lowerValue = value.toLowerCase();
+              if (!['true', 'false', '1', '0', 'y', 'n', 'yes', 'no', '참', '거짓', 'o', 'x'].includes(lowerValue)) {
+                rowErrors.push(`행 ${rowNum}: '${fieldName}' 필드는 불린값이어야 합니다. (현재 값: ${value})`);
+                hasValidationErrors = true;
+              }
+            } else if (typeof value !== 'boolean') {
+              rowErrors.push(`행 ${rowNum}: '${fieldName}' 필드는 불린값이어야 합니다. (현재 값: ${value})`);
+              hasValidationErrors = true;
+            }
+            break;
+        }
+      }
+    });
+    
+    if (hasValidationErrors) {
+      failedData.push({ ...item, rowIndex: index + 1, errors: rowErrors });
+      dataErrors.push(...rowErrors);
+    } else {
+      successData.push(item);
+    }
+  });
+  
+  return { successData, failedData, dataErrors };
+};
